#!/bin/bash
set -euo pipefail
exec 2>>/tmp/haar_error.log

# haar-install-provisioner.sh — install the Windows provisioning payload and the FOG hook.
#
#   sudo haar-install-provisioner.sh
#   sudo haar-install-provisioner.sh --check
#   sudo haar-install-provisioner.sh --no-hook
#
# Inputs:
#   /etc/haar/provisioning.env          rendered by haar-corporate-setup.sh
#   /etc/haar/haar.env                   appliance settings
#   /etc/haar/driver-share.env          generated by haar-driver-share.sh
#
# Output:
#   /images/postdownloadscripts/haar-provisioner/
#     Start-JOGProvisioning.ps1, stage scripts, haar-provisioning.json, SetupComplete.cmd
#   /images/postdownloadscripts/haar-inject-provisioner.sh
#   a source line in /images/postdownloadscripts/fog.postdownload
#
# The rendered config contains the driver-share read password. In Connected mode
# it also contains the join password; in AirGapped mode the join password is
# blank until Resume-JOGCorporateEnrollment.ps1 runs. It is mode 0640 and owned
# by the FOG service user. The /images export is read-only on the isolated
# imaging network.

log()  { echo "[haar-install-provisioner] $*"; }
warn() { echo "[haar-install-provisioner] WARN: $*" >&2; }
die()  { echo "[haar-install-provisioner] ERROR: $*" >&2; exit 1; }

CONFIG=/etc/haar/provisioning.env
JOG_ENV=/etc/haar/haar.env
DRIVER_ENV=/etc/haar/driver-share.env
PAYLOAD_DIR="${Brume_PAYLOAD_DIR:-${JOG_PAYLOAD_DIR:-/images/postdownloadscripts/haar-provisioner}}"
POSTDOWN_DIR=/images/postdownloadscripts
HOOK="$POSTDOWN_DIR/fog.postdownload"
INJECT_NAME=haar-inject-provisioner.sh

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
SRC="${Brume_PROVISIONER_SRC:-${JOG_PROVISIONER_SRC:-/usr/local/share/haar/provisioner/windows}}"
[[ -f "$SRC/Start-JOGProvisioning.ps1" ]] || SRC="$ROOT/provisioner/windows"
INJECT_SRC="${Brume_INJECT_SRC:-${JOG_INJECT_SRC:-/usr/local/share/haar/postdownload/$INJECT_NAME}}"
[[ -f "$INJECT_SRC" ]] || INJECT_SRC="$ROOT/install/postdownload/$INJECT_NAME"

MODE=install
for arg in "$@"; do
  case "$arg" in
    --check) MODE=check ;;
    --no-hook) HOOK="" ;;
    -h|--help) sed -n '2,24p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) die "unknown argument: $arg" ;;
  esac
done

[[ "$(id -u)" -eq 0 ]] || die "run as root: sudo $0"
command -v python3 >/dev/null 2>&1 || die "python3 is required to render the JSON"

FOG_USER="$(id -un fogproject 2>/dev/null || echo root)"
FOG_GROUP="$(id -gn fogproject 2>/dev/null || echo root)"

if [[ "$MODE" == "check" ]]; then
  rc=0
  [[ -f "$CONFIG" ]] || { warn "missing $CONFIG (run haar-corporate-setup.sh)"; rc=1; }
  [[ -f "$SRC/Start-JOGProvisioning.ps1" ]] || { warn "payload source missing: $SRC"; rc=1; }
  [[ -d "$PAYLOAD_DIR" ]] || { warn "payload not installed: $PAYLOAD_DIR"; rc=1; }
  [[ -f "$PAYLOAD_DIR/haar-provisioning.json" ]] || { warn "rendered config missing"; rc=1; }
  if [[ -f "$PAYLOAD_DIR/haar-provisioning.json" ]]; then
    python3 -m json.tool "$PAYLOAD_DIR/haar-provisioning.json" >/dev/null 2>&1 || { warn "rendered config is not valid JSON"; rc=1; }
  fi
  [[ -f "$POSTDOWN_DIR/$INJECT_NAME" ]] || { warn "injection script not installed"; rc=1; }
  if [[ -n "$HOOK" ]]; then
    [[ -f "$HOOK" ]] || { warn "missing $HOOK"; rc=1; }
    grep -qF "$INJECT_NAME" "$HOOK" 2>/dev/null || { warn "$HOOK does not source $INJECT_NAME"; rc=1; }
  fi
  [[ -d /images ]] || { warn "/images not found (is FOG installed?)"; rc=1; }
  if [[ -f "$PAYLOAD_DIR/haar-provisioning.json" ]]; then
    log "payload: $PAYLOAD_DIR"
    log "config : $(python3 -c 'import json,sys; c=json.load(open(sys.argv[1])); print(c.get("Domain","?"), "|", c.get("DomainJoin",{}).get("Mode","?"), "|", c.get("BitLocker",{}).get("Mode","?"))' "$PAYLOAD_DIR/haar-provisioning.json" 2>/dev/null || echo '?')"
  fi
  [[ "$rc" -eq 0 ]] && log "check passed" || log "check found issues"
  exit "$rc"
fi

# --- source configuration --------------------------------------------------

[[ -f "$CONFIG" ]] || die "missing $CONFIG — run: sudo haar-corporate-setup.sh"
[[ -f "$SRC/Start-JOGProvisioning.ps1" ]] || die "payload source missing: $SRC"
[[ -f "$INJECT_SRC" ]] || die "injection script missing: $INJECT_SRC"
[[ -d "$POSTDOWN_DIR" ]] || die "$POSTDOWN_DIR not found — install FOG first"

set -a
# shellcheck disable=SC1091
if [[ -f "$JOG_ENV" ]]; then source "$JOG_ENV"; fi
# shellcheck disable=SC1090
source "$CONFIG"
# shellcheck disable=SC1090
if [[ -f "$DRIVER_ENV" ]]; then source "$DRIVER_ENV"; fi
set +a

# provisioning.env wins when it has a password; otherwise fall back to the generated share env.
READ_PASS="${JOG_DRIVER_READ_PASSWORD:-}"
if [[ -z "$READ_PASS" && -f "$DRIVER_ENV" ]]; then
  # shellcheck disable=SC1090
  source "$DRIVER_ENV"
  READ_PASS="${JOG_DRIVER_READ_PASSWORD:-}"
fi
if [[ -z "$READ_PASS" ]]; then
  warn "driver read password is empty. Run: sudo haar-driver-share.sh --apply"
fi
export JOG_DRIVER_READ_PASSWORD="$READ_PASS"

[[ -n "${JOG_DOMAIN:-}" ]] || die "JOG_DOMAIN is empty in $CONFIG"
[[ "${Brume_DOMAIN_JOIN_MODE:-${JOG_DOMAIN_JOIN_MODE:-Credential}}" =~ ^(Offline|Credential)$ ]] || die "JOG_DOMAIN_JOIN_MODE must be Offline or Credential"
[[ "${Brume_BITLOCKER_ESCROW:-${JOG_BITLOCKER_ESCROW:-AD}}" =~ ^(AD|Entra|Both|None)$ ]] || die "JOG_BITLOCKER_ESCROW must be AD, Entra, Both, or None"
[[ "${Brume_PROVISIONING_MODE:-${JOG_PROVISIONING_MODE:-AirGapped}}" =~ ^(AirGapped|Connected)$ ]] || die "JOG_PROVISIONING_MODE must be AirGapped or Connected"
[[ "${Brume_BITLOCKER_PIN_STORAGE:-${JOG_BITLOCKER_PIN_STORAGE:-None}}" =~ ^(None|LocalDPAPI|ADCustomAttribute)$ ]] || die "JOG_BITLOCKER_PIN_STORAGE is invalid"
if [[ "${Brume_BITLOCKER_PIN_STORAGE:-${JOG_BITLOCKER_PIN_STORAGE:-None}}" == "ADCustomAttribute" && "${Brume_BITLOCKER_ALLOW_AD_PIN_STORAGE:-${JOG_BITLOCKER_ALLOW_AD_PIN_STORAGE:-0}}" != "1" ]]; then
  die "ADCustomAttribute requires JOG_BITLOCKER_ALLOW_AD_PIN_STORAGE=1"
fi

install -d -m 0755 "$PAYLOAD_DIR"

# --- offline join blob -----------------------------------------------------

BLOB_SRC="${JOG_DOMAIN_JOIN_BLOB:-}"
BLOB_WIN='C:\ProgramData\Brume\domainjoin.blob'
rm -f "$PAYLOAD_DIR/domainjoin.blob"
if [[ -n "$BLOB_SRC" && -f "$BLOB_SRC" ]]; then
  install -m 0640 -g "$FOG_GROUP" "$BLOB_SRC" "$PAYLOAD_DIR/domainjoin.blob"
  BLOB_WIN='C:\ProgramData\Brume\domainjoin.blob'
  log "included offline join blob: $BLOB_SRC"
elif [[ -n "$BLOB_SRC" && "$BLOB_SRC" == *\\* ]]; then
  BLOB_WIN="$BLOB_SRC"
  warn "JOG_DOMAIN_JOIN_BLOB looks like a Windows path; it is not copied"
elif [[ "${Brume_DOMAIN_JOIN_MODE:-${JOG_DOMAIN_JOIN_MODE:-Credential}}" == "Offline" ]]; then
  warn "offline join selected but no djoin blob was copied; devices will stay DOMAIN_JOIN_PENDING"
fi
if [[ "${Brume_DOMAIN_JOIN_MODE:-${JOG_DOMAIN_JOIN_MODE:-Credential}}" == "Offline" ]]; then
  warn "one djoin blob joins one computer account: do not deploy this payload to a fleet in Offline mode"
fi
export JOG_DOMAIN_JOIN_BLOB_WIN="$BLOB_WIN"

# --- render the JSON -------------------------------------------------------

OUT="$PAYLOAD_DIR/haar-provisioning.json"
python3 - "$OUT" <<'PY'
import json
import os
import sys


def env(name, default=""):
    return os.environ.get(name, default).strip()


def flag(name, default=False):
    value = env(name, "1" if default else "0").lower()
    return value in ("1", "true", "yes", "on")


def integer(name, default):
    try:
        return int(env(name, str(default)))
    except ValueError:
        return default


groups = [g.strip() for g in env("JOG_AD_GROUPS").split(",") if g.strip()]
try:
    model_map = json.loads(env("JOG_DRIVER_MODEL_MAP", "{}") or "{}")
except json.JSONDecodeError as exc:
    sys.exit(f"JOG_DRIVER_MODEL_MAP is not valid JSON: {exc}")
if not isinstance(model_map, dict):
    sys.exit("JOG_DRIVER_MODEL_MAP must be a JSON object")

config = {
    "Version": 1,
    "Site": env("JOG_SITE_CODE", "SITE01"),
    "Organization": env("JOG_ORG_NAME", "Example Corporation"),
    "DeviceNamePattern": env("JOG_DEVICE_NAME_PATTERN", "LT-{Site}-{Serial}"),
    "ProvisioningMode": env("JOG_PROVISIONING_MODE", "AirGapped"),
    "Domain": env("JOG_DOMAIN"),
    "DomainNetbios": env("JOG_DOMAIN_NETBIOS", "CORP"),
    "DomainJoin": {
        "Mode": env("JOG_DOMAIN_JOIN_MODE", "Credential"),
        "BlobPath": env("JOG_DOMAIN_JOIN_BLOB_WIN", r"C:\ProgramData\Brume\domainjoin.blob"),
        "User": env("JOG_DOMAIN_JOIN_USER"),
        "Password": env("JOG_DOMAIN_JOIN_PASSWORD"),
        "OUPath": env("JOG_DOMAIN_JOIN_OU"),
    },
    "HybridJoin": {
        "Enabled": flag("JOG_HYBRID_JOIN", True),
        "TimeoutMinutes": integer("JOG_HYBRID_JOIN_TIMEOUT_MIN", 30),
    },
    "Groups": groups,
    "GroupsMode": env("JOG_GROUPS_MODE", "Device"),
    "BitLocker": {
        "Enabled": flag("JOG_BITLOCKER_ENABLED", True),
        "Mode": env("JOG_BITLOCKER_MODE", "TpmOnly"),
        "PinLength": integer("JOG_BITLOCKER_PIN_LENGTH", 6),
        "Escrow": env("JOG_BITLOCKER_ESCROW", "AD"),
        "PinStorage": env("JOG_BITLOCKER_PIN_STORAGE", "None"),
        "AllowAdPinStorage": flag("JOG_BITLOCKER_ALLOW_AD_PIN_STORAGE", False),
        "AdPinAttribute": env("JOG_BITLOCKER_AD_PIN_ATTRIBUTE", "extensionAttribute15"),
    },
    "DriverShare": {
        "Unc": env("JOG_DRIVER_SHARE_UNC", r"\\10.99.0.1\Drivers"),
        "ReadUser": env("JOG_DRIVER_READ_USER", "drivers"),
        "ReadPassword": env("JOG_DRIVER_READ_PASSWORD"),
        "ModelMap": model_map,
        "Fallback": env("JOG_DRIVER_FALLBACK", "Default"),
        "BasePacks": [p.strip() for p in env("JOG_DRIVER_BASE_PACKS", "VMD").split(",") if p.strip()],
        "Manifest": env("JOG_DRIVER_MANIFEST", "manifest.json"),
    },
    "RebootBetweenStages": flag("JOG_PROVISIONING_REBOOT_BETWEEN_STAGES", True),
    "DeleteConfigOnComplete": flag("JOG_PROVISIONING_DELETE_CONFIG_ON_COMPLETE", True),
    "ShutdownOnComplete": flag("JOG_PROVISIONING_SHUTDOWN_ON_COMPLETE", False),
    "MaxAttempts": integer("JOG_PROVISIONING_MAX_ATTEMPTS", 5),
}

with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump(config, handle, indent=2, ensure_ascii=False)
    handle.write("\n")
PY

# --- install payload -------------------------------------------------------

cp -a "$SRC"/. "$PAYLOAD_DIR"/
# The example config is documentation, not the live config.
rm -f "$PAYLOAD_DIR/haar-provisioning.example.json"

find "$PAYLOAD_DIR" -type d -exec chmod 0755 {} +
find "$PAYLOAD_DIR" -type f -exec chmod 0644 {} +
chmod 0640 "$OUT"
if [[ -f "$PAYLOAD_DIR/domainjoin.blob" ]]; then chmod 0640 "$PAYLOAD_DIR/domainjoin.blob"; fi
chown -R "$FOG_USER:$FOG_GROUP" "$PAYLOAD_DIR"

# --- install injection + hook ---------------------------------------------

install -m 0755 -o "$FOG_USER" -g "$FOG_GROUP" "$INJECT_SRC" "$POSTDOWN_DIR/$INJECT_NAME"

if [[ -n "$HOOK" ]]; then
  [[ -f "$HOOK" ]] || die "missing $HOOK"
  if ! grep -qF "$INJECT_NAME" "$HOOK"; then
    BACKUP="${HOOK}.bak-haar-$(date +%Y%m%d-%H%M%S)"
    cp -a "$HOOK" "$BACKUP"
    {
      echo
      echo "## Brume corporate provisioner payload (no-op if not installed)"
      echo "[ -f \"\${postdownpath}${INJECT_NAME}\" ] && . \"\${postdownpath}${INJECT_NAME}\""
    } >> "$HOOK"
    chown "$FOG_USER:$FOG_GROUP" "$HOOK"
    log "added the provisioner hook to $HOOK (backup: $BACKUP)"
  else
    log "hook already present in $HOOK"
  fi
fi

log "payload installed: $PAYLOAD_DIR"
log "rendered config : $OUT (0640, $FOG_USER:$FOG_GROUP)"
log "injection hook  : $POSTDOWN_DIR/$INJECT_NAME"
log "next            : deploy an image; the payload is copied to C:\\ProgramData\\Brume on first boot"
